def transform(grid):
    # Remove isolated marker cells from uniform-color rectangular objects.
    h,w=len(grid),len(grid[0])
    # Identify dominant background (typically 9 in demos, 6 here).
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    # Convert singleton non-background intrusions within solid color regions to that region's base color.
    # Find large monochrome rectangular components; replace other colored dots within their bounding rectangles.
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       col=grid[r][c]
       if col==bg or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); cells=[]
       while st:
        y,x=st.pop(); cells.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         Y,X=y+dy,x+dx
         if 0<=Y<h and 0<=X<w and (Y,X) not in seen and grid[Y][X]==col:
          seen.add((Y,X));st.append((Y,X))
       ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
       a,b=min(ys),max(ys);x,z=min(xs),max(xs)
       if len(cells)>=4 and len(cells)/((b-a+1)*(z-x+1))>.7: comps.append((col,a,b,x,z))
    # Any foreign singleton inside a rectangular object is noise. Demo illustrates eradication
    # of all non-object marks from large framed/filled shapes; keep remaining input otherwise.
    for col,a,b,x,z in comps:
      for r in range(a,b+1):
       for c in range(x,z+1):
        if grid[r][c]!=bg: out[r][c]=col
    return out
